  var n = normalize(f.worldNormal);
  let vw = normalize(fr.cameraPos.xyz - f.worldPos);
  // Flip for back faces is unnecessary (back-face culling), but guard degenerate normals.
  if (dot(n, n) < 0.5) { n = vec3<f32>(0.0, 1.0, 0.0); }

